# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import uncovered_labels

OPEN = parse_span("09:00-17:00")


class UncoveredLabelTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [
            parse_span("09:00-12:00"),
            parse_span("13:00-17:00")
        ]
        self.assertEqual(
            uncovered_labels(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        worked = [parse_span("10:00-16:00")]
        self.assertEqual(
            uncovered_labels(worked, OPEN),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:00-17:00 (60 min)"
            ]
        )

    def test_overlapping_and_unsorted_spans(self):
        worked = [
            parse_span("13:00-17:00"),
            parse_span("09:00-13:30"),
            parse_span("11:00-12:00")
        ]
        self.assertEqual(uncovered_labels(worked, OPEN), [])

    def test_no_one_worked(self):
        self.assertEqual(
            uncovered_labels([], OPEN),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        self.assertEqual(uncovered_labels([OPEN], OPEN), [])

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            uncovered_labels([Span(480, 600)], OPEN)

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            uncovered_labels([Span(960, 1080)], OPEN)


if __name__ == "__main__":
    unittest.main()
